"""Reporting from sealed/evaluated artifacts only; no policy rerun or tuning."""
import json
from pathlib import Path
import pandas as pd
from p10_step2e_data import ROOT,OUT,sha,save,utc


def table(df):
    def val(v):
        if pd.isna(v):return 'N/A'
        if isinstance(v,float):return f'{v:.4f}'
        return str(v)
    cols=list(df.columns)
    return '| '+' | '.join(cols)+' |\n| '+' | '.join(['---']*len(cols))+' |\n'+'\n'.join('| '+' | '.join(val(v) for v in row)+' |' for row in df.itertuples(index=False,name=None))+'\n'


def main():
    r=OUT/'results';u=pd.read_csv(r/'units.csv');p=pd.read_csv(r/'primary_case_results.csv');prom=pd.read_csv(r/'promotions.csv');lf=pd.read_csv(r/'long_faults.csv');cv=pd.read_csv(r/'physical_segment_cv.csv');d=pd.read_csv(r/'case_deltas.csv');meta=json.loads((OUT/'evaluator_metadata.json').read_text());proof=json.loads((r/'evaluation_start.json').read_text());config=json.loads((OUT/'run/policy_config.json').read_text())
    prim=p[p.policy!='H_hold'];fault=prim[prim.arm=='fault'];sp=prim[prim.arm=='setpoint']
