    robust=u[u.policy=='DEph_cv'].groupby(['machine','op']).agg(AP=('AP','mean'),fault_written=('fault_written_fraction','mean'),fault_promotions=('fault_false_promotions','sum'),NORMAL_B_FPR=('normal_B_FPR','mean'),NORMAL_B_written=('normal_B_written_fraction','mean'),early_promotions=('transition_period_promotions','sum'),safe_promotions=('normal_B_safe_promotions','sum')).reset_index()
